  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+template+'"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'12');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.value,n.min,n.max,n.step].join(',')),'4,2,9,1');assert.equal(await page.$('[data-motion-stream="cardRatio"]'),null);for(const [key,spec] of [['gap','3,0,10,0.5'],['dimming','45,0,80,5']])assert.equal(await page.$eval('[data-motion-stream="'+key+'"]',n=>[n.value,n.min,n.max,n.step].join(',')),spec);
