  const reuse=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id];for(let i=0;i<80;i++)clock.set(i/80);const native=d.createElement;let created=0;d.createElement=function(...a){if(a[0]==='canvas')created++;return native.apply(this,a);};try{for(let i=0;i<80;i++)clock.set(i/80);return created;}finally{d.createElement=native;}});assert.equal(reuse,0);await change('[data-motion-stream="cornerRadius"]','3');await change('[data-motion-stream="frameRatio"]','16:9');console.log('Spotlight Zoom pixels: every source expands/holds/returns, active foreground native selection, configurable background fade, single intrinsic alpha, rounded zoom corners/outside shadows, dynamic authored cover crops and zero warmed source canvas allocations OK');
