  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',(n,template)=>n.value='Mi '+template,template);await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,template);assert.equal(saved.assets.length,4);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'50');const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,outside:sec().elements[0],enabled:sec().sdEnabled,length:sec().sdLength};});assert.deepEqual(inserted.outside,before.outside);assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-spotlight-surface'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#spotlight-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#spotlight-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#spotlight-export',inserted.gid);await page.evaluate(()=>document.querySelector('#spotlight-export').remove());
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$$eval('[data-motion-template]',ns=>ns.every(n=>n.disabled)),true);await change('[data-motion-stream="dimming"]','65');await page.$eval('#preview',f=>f.contentDocument.body.dataset.spotlightSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.spotlightSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id];},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="dimming"]',n=>n.value),'65');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#spotlight-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#spotlight-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});await page.evaluate(()=>document.querySelector('#spotlight-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),template);
